bad = []
for f, (h, text) in FILES.items():
    ast.parse(text)
    p = pathlib.Path(f)
    if p.exists() and p.read_text() == text:      # もう版101 の形なら、そのままで良い
        continue
    if h is None:
        if p.exists():
            bad.append(f + "（もうある）")
    elif not p.exists() or hashlib.sha256(p.read_bytes()).hexdigest() != h:
        bad.append(f)
if bad:
    sys.exit(f"⚠️ {bad} が版100 を当てたままの形ではない（手で直した所があるか、版が違う）。何も書き換えていない")
